/**
 * Opt-in channel watch: dispatch on posts in allowlisted channels.
 *
 * Filtering rules (the anti-slop guarantees):
 * - The allowlist is a finite id list, or a lone `"*"` for every channel
 *   the bot is in. Mixing `"*"` with ids is a definition error.
 * - Top-level posts only by default. `"replies"` is thread replies only
 *   (`ts !== threadTs`). `"all"` is both. A lone `"*"` is replies only, or
 *   `"all"` with `includeBotPosts` (hosted edges bound the top-level posts).
 * - `replies: "joined"` also takes thread replies from every channel the
 *   bot is in, whatever the allowlist and `posts` say about that channel.
 * - Posts that @mention the bot are skipped here (the `app_mention` path
 *   owns them).
 * - Bot-authored posts are dropped unless `includeBotPosts` is configured
 *   (alert feeds / webhook integrations); the watching bot's own posts are
 *   always dropped either way (loop safety).
 * - An optional debounce window lets rapid edits settle: edits update the
 *   pending text, deleting the post cancels the dispatch.
 */
import { defaultSlackLog } from "./log.js";
const CHANNEL_ID_PATTERN = /^[CG][A-Z0-9]+$/;
/**
 * Channel-watch allowlist contract, mirrored by the control plane's
 * deploy-time validation (proto posture: both sides validate
 * independently). Ids are required because on Cursor-managed hosting they
 * become channel-scoped subscription edges — the control plane drops
 * channel posts outside the id set before any compute wakes, and it cannot
 * resolve `#names`.
 */
export const CHANNEL_POSTS_MAX_CHANNEL_IDS = 10;
/**
 * True when the allowlist is only `"*"`: every channel the bot is in.
 * Guest-side only. It is not a deploy-manifest subscription — the control
 * plane rejects `"*"` and already delivers a reply in a thread a mention
 * started. Top-level posts match it only under `posts: "all"` with
 * `includeBotPosts`, and on hosting only in channels with an edge.
 */
export function channelPostsWatchEverywhere(entries) {
    const trimmed = entries.map((entry) => entry.trim()).filter((entry) => entry !== "");
    return trimmed.length > 0 && trimmed.every((entry) => entry === "*");
}
/** The channel-id (`C…`/`G…`) entries of an allowlist, deduped. */
export function channelPostIdEntries(entries) {
    const ids = new Set();
    for (const raw of entries) {
        const entry = raw.trim();
        if (CHANNEL_ID_PATTERN.test(entry)) {
            ids.add(entry);
        }
    }
    return [...ids];
}
/**
 * Validate `channelPosts.allow` at definition time. Returns an actionable
 * error string (to be prefixed with the option path), or undefined.
 */
export function validateChannelPostsAllow(entries) {
    if (channelPostsWatchEverywhere(entries)) {
        return undefined;
    }
    if (entries.some((entry) => entry.trim() === "*")) {
        return ('must not mix "*": a lone "*" watches every channel the bot is in, ' +
            "thread replies only. Otherwise list channel ids (C…/G…), up to " +
            `${CHANNEL_POSTS_MAX_CHANNEL_IDS} channels.`);
    }
    const ids = channelPostIdEntries(entries);
    if (ids.length === 0) {
        return ("must include at least one channel id (C…/G…). Ids define the " +
            "watched set on Cursor-managed hosting; `#name` entries alone are " +
            "not enough.");
    }
    if (ids.length > CHANNEL_POSTS_MAX_CHANNEL_IDS) {
        return `lists ${ids.length} channel ids; the maximum is ${CHANNEL_POSTS_MAX_CHANNEL_IDS}.`;
    }
    return undefined;
}
/** Allowlist over channel ids and `#names` (names resolve lazily). */
export class SlackChannelAllowlist {
    constructor(entries) {
        this.ids = new Set();
        this.names = new Set();
        this.everywhere = channelPostsWatchEverywhere(entries);
        if (this.everywhere) {
            return;
        }
        for (const raw of entries) {
            const entry = raw.trim();
            // A mixed "*" is a definition error. Ignore it here so a stale
            // config degrades to its explicit entries instead of matching all.
            if (entry === "" || entry === "*") {
                continue;
            }
            if (entry.startsWith("#")) {
                this.names.add(entry.slice(1).toLowerCase());
            }
            else if (CHANNEL_ID_PATTERN.test(entry)) {
                this.ids.add(entry);
            }
            else {
                // Bare name without "#" — treat as a name for forgiving authoring.
                this.names.add(entry.toLowerCase());
            }
        }
    }
    matches(channelId) {
        return this.everywhere || this.ids.has(channelId);
    }
    unresolvedNames() {
        return [...this.names];
    }
    /** Fold resolved `name → id` pairs into the id set. */
    applyResolvedNames(resolved) {
        for (const name of this.names) {
            const id = resolved.get(name);
            if (id !== undefined) {
                this.ids.add(id);
            }
        }
    }
}
/**
 * Resolve channel `#names` to ids via `conversations.list`. Best-effort:
 * returns whatever resolved; the caller logs names that stayed unresolved.
 */
export async function resolveChannelNames(client, names, log = defaultSlackLog) {
    const wanted = new Set(names.map((name) => name.toLowerCase()));
    const resolved = new Map();
    if (wanted.size === 0) {
        return resolved;
    }
    let cursor;
    for (let page = 0; page < 20 && resolved.size < wanted.size; page += 1) {
        const response = await client.conversations.list({
            types: "public_channel,private_channel",
            exclude_archived: true,
            limit: 200,
            ...(cursor === undefined ? {} : { cursor }),
        });
        for (const channel of response.channels ?? []) {
            const name = channel.name?.toLowerCase();
            if (name !== undefined && wanted.has(name) && channel.id !== undefined) {
                resolved.set(name, channel.id);
            }
        }
        cursor = response.response_metadata?.next_cursor || undefined;
        if (cursor === undefined) {
            break;
        }
    }
    for (const name of wanted) {
        if (!resolved.has(name)) {
            log.error("channel watch: could not resolve channel name", {
                name: `#${name}`,
            });
        }
    }
    return resolved;
}
export function createChannelPostWatcher(args) {
    const log = args.log ?? defaultSlackLog;
    const posts = args.options.posts ?? "top-level";
    const joinedReplies = args.options.replies === "joined";
    const includeBotPosts = args.options.includeBotPosts === true;
    const debounceMs = args.options.debounceMs ?? 0;
    const pending = new Map();
    const pendingKey = (channelId, ts) => `${channelId}:${ts}`;
    function skip(reason, message) {
        log.debug(`channel watch skip (${reason})`, {
            channel: message.channelId,
            message_ts: message.ts,
            thread_ts: message.threadTs,
        });
        return true;
    }
    function fire(message, eventId) {
        log.info("channel watch dispatch", {
            channel: message.channelId,
            message_ts: message.ts,
            thread_ts: message.threadTs,
            event_id: eventId,
        });
        args.dispatch(message, eventId);
    }
    return {
        handle(event, eventId) {
            if (event.kind === "deleted") {
                const key = pendingKey(event.channelId, event.ts);
                const entry = pending.get(key);
                if (entry !== undefined) {
                    clearTimeout(entry.timer);
                    pending.delete(key);
                    log.info("channel watch cancel (post deleted)", {
                        channel: event.channelId,
                        message_ts: event.ts,
                    });
                }
                return true;
            }
            const message = event.message;
            const reply = message.ts !== message.threadTs;
            const joinedReply = joinedReplies && reply;
            if (!joinedReply && !args.allowlist.matches(message.channelId)) {
                return skip("channel not allowlisted", message);
            }
            if (event.kind === "edited") {
                const entry = pending.get(pendingKey(message.channelId, message.ts));
                if (entry !== undefined) {
                    entry.message = { ...entry.message, ...message };
                }
                // Edits never (re-)dispatch on their own.
                return true;
            }
            if (posts === "replies" && !reply) {
                return skip("top-level post (posts: replies)", message);
            }
            if (posts === "top-level" && reply && !joinedReply) {
                return skip("thread reply (posts: top-level)", message);
            }
            const botUserId = args.getBotUserId();
            const author = message.author;
            if (author?.isBot === true) {
                if (!includeBotPosts) {
                    return skip("bot-authored post (includeBotPosts off)", message);
                }
                const selfBotId = args.getBotId?.();
                if (selfBotId === undefined && botUserId === undefined) {
                    return skip("bot-authored post (bot identity unknown; loop safety)", message);
                }
                if ((selfBotId !== undefined && author.botId === selfBotId) ||
                    (botUserId !== undefined && author.userId !== "" && author.userId === botUserId)) {
                    return skip("own post (loop safety)", message);
                }
            }
            if (botUserId !== undefined && message.text.includes(`<@${botUserId}>`)) {
                return skip("bot mention (app_mention path owns it)", message);
            }
            if (debounceMs <= 0) {
                fire(message, eventId);
                return true;
            }
            const key = pendingKey(message.channelId, message.ts);
            const existing = pending.get(key);
            if (existing !== undefined) {
                clearTimeout(existing.timer);
            }
            const entry = {
                timer: setTimeout(() => {
                    pending.delete(key);
                    fire(entry.message, entry.eventId);
                }, debounceMs),
                message,
                ...(eventId === undefined ? {} : { eventId }),
            };
            pending.set(key, entry);
            return true;
        },
        stop() {
            for (const entry of pending.values()) {
                clearTimeout(entry.timer);
            }
            pending.clear();
        },
    };
}
